pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) internal {
        vm.assume(true);
        uint256 basefeeBefore;
        try c.basefee() returns (uint256 __r) { basefeeBefore = __r; } catch { return; }
        uint256 overheadBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { overheadBefore = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(n, t, f, h, s, b, o, sc) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.basefee() == basefeeBefore && c.l1FeeOverhead() == overheadBefore);
    }

    function testFuzz_run(uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) public {
        _run(n, t, f, h, s, b, o, sc);
    }

    receive() external payable {}
}
